import{_ as t,a0 as o,w as d,s as h,I as n,x as a,a1 as i,A as p,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"不可或缺的 Bash 别名 | LCTT x X-CMD","titleTemplate":false,"description":"不可或缺的 Bash 别名 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"不可或缺的 Bash 别名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"不可或缺的 Bash 别名 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190731 Bash aliases you can-t live without","title":"不可或缺的 Bash 别名","tag":"201908","desc":""},"relativePath":"201908/20190731 Bash aliases you can-t live without.md","filePath":"[post].md"}'),r={name:"201908/20190731 Bash aliases you can-t live without.md"};function c(g,s,k,u,b,f){const e=o("Link");return d(),h("div",null,[s[44]||(s[44]=n("h1",{id:"不可或缺的-bash-别名",tabindex:"-1"},[a("不可或缺的 Bash 别名 "),n("a",{class:"header-anchor",href:"#不可或缺的-bash-别名","aria-label":"Permalink to “不可或缺的 Bash 别名”"},"​")],-1)),s[45]||(s[45]=n("blockquote",null,[n("p",null,"厌倦了一遍又一遍地输入相同的长命令？你觉得在命令行上工作效率低吗？Bash 别名可以为你创造一个与众不同的世界。")],-1)),s[46]||(s[46]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/03/095855ip0h0jpi5u9t3r00.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("Bash 别名是一种用新的命令补充或覆盖 Bash 命令的方法。Bash 别名使用户可以轻松地在 ",-1)),i(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:p(()=>[...s[0]||(s[0]=[a("POSIX",-1)])]),_:1}),s[2]||(s[2]=a(" 终端中自定义其体验。它们通常定义在 ",-1)),s[3]||(s[3]=n("code",null,"$HOME/.bashrc",-1)),s[4]||(s[4]=a(" 或 ",-1)),s[5]||(s[5]=n("code",null,"$HOME/bash_aliases",-1)),s[6]||(s[6]=a(" 中（它是由 ",-1)),s[7]||(s[7]=n("code",null,"$HOME/.bashrc",-1)),s[8]||(s[8]=a(" 加载的）。",-1))]),s[47]||(s[47]=l(`<p>大多数发行版在新用户帐户的默认 <code>.bashrc</code> 文件中至少添加了一些流行的别名。这些可以用来简单演示 Bash 别名的语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ls=&#39;ls -F&#39;</span></span>
<span class="line"><span>alias ll=&#39;ls -lh&#39;</span></span></code></pre></div><p>但并非所有发行版都附带预先添加好的别名。如果你想手动添加别名，则必须将它们加载到当前的 Bash 会话中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>否则，你可以关闭终端并重新打开它，以便重新加载其配置文件。</p>`,5)),n("p",null,[s[10]||(s[10]=a("通过 Bash 初始化脚本中定义的那些别名，你可以键入 ",-1)),s[11]||(s[11]=n("code",null,"ll",-1)),s[12]||(s[12]=a(" 而得到 ",-1)),s[13]||(s[13]=n("code",null,"ls -l",-1)),s[14]||(s[14]=a(" 的结果，当你键入 ",-1)),s[15]||(s[15]=n("code",null,"ls",-1)),s[16]||(s[16]=a(" 时，得到也不是原来的 ",-1)),i(e,{href:"https://opensource.com/article/19/7/master-ls-command"},{default:p(()=>[...s[9]||(s[9]=[a("ls",-1)])]),_:1}),s[17]||(s[17]=a(" 的普通输出。",-1))]),s[48]||(s[48]=l(`<p>那些别名很棒，但它们只是浅尝辄止。以下是十大 Bash 别名，一旦你试过它们，你会发现再也不能离开它们。</p><h3 id="首先设置" tabindex="-1">首先设置 <a class="header-anchor" href="#首先设置" aria-label="Permalink to “首先设置”">​</a></h3><p>在开始之前，创建一个名为 <code>~/.bash_aliases</code> 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch ~/.bash_aliases</span></span></code></pre></div><p>然后，确认这些代码出现在你的 <code>~/.bashrc</code> 文件当中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -e $HOME/.bash_aliases ]; then</span></span>
<span class="line"><span>    source $HOME/.bash_aliases</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>如果你想亲自尝试本文中的任何别名，请将它们输入到 <code>.bash_aliases</code> 文件当中，然后使用 <code>source ~/.bashrc</code> 命令将它们加载到当前 Bash 会话中。</p><h3 id="按文件大小排序" tabindex="-1">按文件大小排序 <a class="header-anchor" href="#按文件大小排序" aria-label="Permalink to “按文件大小排序”">​</a></h3><p>如果你一开始使用过 GNOME 中的 Nautilus、MacOS 中的 Finder 或 Windows 中的资源管理器等 GUI 文件管理器，那么你很可能习惯了按文件大小排序文件列表。你也可以在终端上做到这一点，但这条命令不是很简洁。</p><p>将此别名添加到 GNU 系统上的配置中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lt=&#39;ls --human-readable --size -1 -S --classify&#39;</span></span></code></pre></div><p>此别名将 <code>lt</code> 替换为 <code>ls</code> 命令，该命令在单个列中显示每个项目的大小，然后按大小对其进行排序，并使用符号表示文件类型。加载新别名，然后试一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span>
<span class="line"><span>$ lt</span></span>
<span class="line"><span>total 344K</span></span>
<span class="line"><span>140K configure*</span></span>
<span class="line"><span> 44K aclocal.m4</span></span>
<span class="line"><span> 36K LICENSE</span></span>
<span class="line"><span> 32K config.status*</span></span>
<span class="line"><span> 24K Makefile</span></span>
<span class="line"><span> 24K Makefile.in</span></span>
<span class="line"><span> 12K config.log</span></span>
<span class="line"><span>8.0K README.md</span></span>
<span class="line"><span>4.0K info.slackermedia.Git-portal.json</span></span>
<span class="line"><span>4.0K git-portal.spec</span></span>
<span class="line"><span>4.0K flatpak.path.patch</span></span>
<span class="line"><span>4.0K Makefile.am*</span></span>
<span class="line"><span>4.0K dot-gitlab.ci.yml</span></span>
<span class="line"><span>4.0K configure.ac*</span></span>
<span class="line"><span>   0 autom4te.cache/</span></span>
<span class="line"><span>   0 share/</span></span>
<span class="line"><span>   0 bin/</span></span>
<span class="line"><span>   0 install-sh@</span></span>
<span class="line"><span>   0 compile@</span></span>
<span class="line"><span>   0 missing@</span></span>
<span class="line"><span>   0 COPYING@</span></span></code></pre></div><p>在 MacOS 或 BSD 上，<code>ls</code> 命令没有相同的选项，因此这个别名可以改为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lt=&#39;du -sh * | sort -h&#39;</span></span></code></pre></div><p>这个版本的结果稍有不同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du -sh * | sort -h</span></span>
<span class="line"><span>0       compile</span></span>
<span class="line"><span>0       COPYING</span></span>
<span class="line"><span>0       install-sh</span></span>
<span class="line"><span>0       missing</span></span>
<span class="line"><span>4.0K    configure.ac</span></span>
<span class="line"><span>4.0K    dot-gitlab.ci.yml</span></span>
<span class="line"><span>4.0K    flatpak.path.patch</span></span>
<span class="line"><span>4.0K    git-portal.spec</span></span>
<span class="line"><span>4.0K    info.slackermedia.Git-portal.json</span></span>
<span class="line"><span>4.0K    Makefile.am</span></span>
<span class="line"><span>8.0K    README.md</span></span>
<span class="line"><span>12K     config.log</span></span>
<span class="line"><span>16K     bin</span></span>
<span class="line"><span>24K     Makefile</span></span>
<span class="line"><span>24K     Makefile.in</span></span>
<span class="line"><span>32K     config.status</span></span>
<span class="line"><span>36K     LICENSE</span></span>
<span class="line"><span>44K     aclocal.m4</span></span>
<span class="line"><span>60K     share</span></span>
<span class="line"><span>140K    configure</span></span>
<span class="line"><span>476K    autom4te.cache</span></span></code></pre></div><p>实际上，即使在 Linux上，上面这个命令也很有用，因为使用 <code>ls</code> 列出的目录和符号链接的大小为 0，这可能不是你真正想要的信息。使用哪个看你自己的喜好。</p><p><em>感谢 Brad Alexander 提供的这个别名的思路。</em></p><h3 id="只查看挂载的驱动器" tabindex="-1">只查看挂载的驱动器 <a class="header-anchor" href="#只查看挂载的驱动器" aria-label="Permalink to “只查看挂载的驱动器”">​</a></h3><p><code>mount</code> 命令过去很简单。只需一个命令，你就可以获得计算机上所有已挂载的文件系统的列表，它经常用于概览连接到工作站有哪些驱动器。在过去看到超过三、四个条目就会令人印象深刻，因为大多数计算机没有那么多的 USB 端口，因此这个结果还是比较好查看的。</p><p>现在计算机有点复杂，有 LVM、物理驱动器、网络存储和虚拟文件系统，<code>mount</code> 的结果就很难一目了然：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sysfs on /sys type sysfs (rw,nosuid,nodev,noexec,relatime,seclabel)</span></span>
<span class="line"><span>proc on /proc type proc (rw,nosuid,nodev,noexec,relatime)</span></span>
<span class="line"><span>devtmpfs on /dev type devtmpfs (rw,nosuid,seclabel,size=8131024k,nr_inodes=2032756,mode=755)</span></span>
<span class="line"><span>securityfs on /sys/kernel/security type securityfs (rw,nosuid,nodev,noexec,relatime)</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>/dev/nvme0n1p2 on /boot type ext4 (rw,relatime,seclabel)</span></span>
<span class="line"><span>/dev/nvme0n1p1 on /boot/efi type vfat (rw,relatime,fmask=0077,dmask=0077,codepage=437,iocharset=ascii,shortname=winnt,errors=remount-ro)</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>gvfsd-fuse on /run/user/100977/gvfs type fuse.gvfsd-fuse (rw,nosuid,nodev,relatime,user_id=100977,group_id=100977)</span></span>
<span class="line"><span>/dev/sda1 on /run/media/seth/pocket type ext4 (rw,nosuid,nodev,relatime,seclabel,uhelper=udisks2)</span></span>
<span class="line"><span>/dev/sdc1 on /run/media/seth/trip type ext4 (rw,nosuid,nodev,relatime,seclabel,uhelper=udisks2)</span></span>
<span class="line"><span>binfmt_misc on /proc/sys/fs/binfmt_misc type binfmt_misc (rw,relatime)</span></span></code></pre></div><p>要解决这个问题，试试这个别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias mnt=&#39;mount | awk -F&#39; &#39; &#39;{ printf &quot;%s\\t%s\\n&quot;,$1,$3; }&#39; | column -t | egrep ^/dev/ | sort&#39;</span></span></code></pre></div><p>此别名使用 <code>awk</code> 按列解析 <code>mount</code> 的输出，将输出减少到你可能想要查找的内容（挂载了哪些硬盘驱动器，而不是文件系统）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mnt</span></span>
<span class="line"><span>/dev/mapper/fedora-root  /</span></span>
<span class="line"><span>/dev/nvme0n1p1           /boot/efi</span></span>
<span class="line"><span>/dev/nvme0n1p2           /boot</span></span>
<span class="line"><span>/dev/sda1                /run/media/seth/pocket</span></span>
<span class="line"><span>/dev/sdc1                /run/media/seth/trip</span></span></code></pre></div><p>在 MacOS 上，<code>mount</code> 命令不提供非常详细的输出，因此这个别名可能过度精简了。但是，如果你更喜欢简洁的报告，请尝试以下方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias mnt=&#39;mount | grep -E ^/dev | column -t&#39;</span></span></code></pre></div><p>结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mnt</span></span>
<span class="line"><span>/dev/disk1s1  on  /                (apfs,  local,  journaled)</span></span>
<span class="line"><span>/dev/disk1s4  on  /private/var/vm  (apfs,  local,  noexec,     journaled,  noatime,  nobrowse)</span></span></code></pre></div><h3 id="在你的-grep-历史中查找命令" tabindex="-1">在你的 grep 历史中查找命令 <a class="header-anchor" href="#在你的-grep-历史中查找命令" aria-label="Permalink to “在你的 grep 历史中查找命令”">​</a></h3><p>有时你好不容易弄清楚了如何在终端完成某件事，并觉得自己永远不会忘记你刚学到的东西。然后，一个小时过去之后你就完全忘记了你做了什么。</p><p>搜索 Bash 历史记录是每个人不时要做的事情。如果你确切地知道要搜索的内容，可以使用 <code>Ctrl + R</code> 对历史记录进行反向搜索，但有时你无法记住要查找的确切命令。</p><p>这是使该任务更容易的别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias gh=&#39;history|grep&#39;</span></span></code></pre></div><p>这是如何使用的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gh bash</span></span>
<span class="line"><span>482 cat ~/.bashrc | grep _alias</span></span>
<span class="line"><span>498 emacs ~/.bashrc</span></span>
<span class="line"><span>530 emacs ~/.bash_aliases</span></span>
<span class="line"><span>531 source ~/.bashrc</span></span></code></pre></div><h3 id="按修改时间排序" tabindex="-1">按修改时间排序 <a class="header-anchor" href="#按修改时间排序" aria-label="Permalink to “按修改时间排序”">​</a></h3><p>每个星期一都会这样：你坐在你的电脑前开始工作，你打开一个终端，你发现你已经忘记了上周五你在做什么。你需要的是列出最近修改的文件的别名。</p><p>你可以使用 <code>ls</code> 命令创建别名，以帮助你找到上次离开的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias left=&#39;ls -t -1&#39;</span></span></code></pre></div><p>输出很简单，但如果你愿意，可以使用 <code>--long</code> 选项扩展它。这个别名列出的显示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ left</span></span>
<span class="line"><span>demo.jpeg</span></span>
<span class="line"><span>demo.xcf</span></span>
<span class="line"><span>design-proposal.md</span></span>
<span class="line"><span>rejects.txt</span></span>
<span class="line"><span>brainstorm.txt</span></span>
<span class="line"><span>query-letter.xml</span></span></code></pre></div><h3 id="文件计数" tabindex="-1">文件计数 <a class="header-anchor" href="#文件计数" aria-label="Permalink to “文件计数”">​</a></h3><p>如果你需要知道目录中有多少文件，那么该解决方案是 UNIX 命令构造的最典型示例之一：使用 <code>ls</code> 命令列出文件，用<code>-1</code> 选项将其输出控制为只有一列，然后输出到 <code>wc</code>（单词计数）命令的管道，以计算有多少行。</p><p>这是 UNIX 理念如何允许用户使用小型的系统组件构建自己的解决方案的精彩演示。如果你碰巧每天都要做几次，这个命令组合也要输入很多字母，如果没有使用 <code>-R</code> 选项，它就不能用于目录，这会为输出引入新行并导致无用的结果。</p><p>而这个别名使这个过程变得简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias count=&#39;find . -type f | wc -l&#39;</span></span></code></pre></div><p>这个别名会计算文件，忽略目录，但<strong>不会</strong>忽略目录的内容。如果你有一个包含两个目录的项目文件夹，每个目录包含两个文件，则该别名将返回 4，因为整个项目中有 4 个文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>foo   bar</span></span>
<span class="line"><span>$ count</span></span>
<span class="line"><span>4</span></span></code></pre></div><h3 id="创建-python-虚拟环境" tabindex="-1">创建 Python 虚拟环境 <a class="header-anchor" href="#创建-python-虚拟环境" aria-label="Permalink to “创建 Python 虚拟环境”">​</a></h3><p>你用 Python 编程吗？</p><p>你用 Python 编写了很多程序吗？</p><p>如果是这样，那么你就知道创建 Python 虚拟环境至少需要 53 次击键。</p><p>这个数字里有 49 次是多余的，它很容易被两个名为 <code>ve</code> 和 <code>va</code> 的新别名所解决：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ve=&#39;python3 -m venv ./venv&#39;</span></span>
<span class="line"><span>alias va=&#39;source ./venv/bin/activate&#39;</span></span></code></pre></div><p>运行 <code>ve</code> 会创建一个名为 <code>venv</code> 的新目录，其中包含 Python 3 的常用虚拟环境文件系统。<code>va</code> 别名在当前 shell 中的激活该环境：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd my-project</span></span>
<span class="line"><span>$ ve</span></span>
<span class="line"><span>$ va</span></span>
<span class="line"><span>(venv) $</span></span></code></pre></div><h3 id="增加一个复制进度条" tabindex="-1">增加一个复制进度条 <a class="header-anchor" href="#增加一个复制进度条" aria-label="Permalink to “增加一个复制进度条”">​</a></h3><p>每个人都会吐槽进度条，因为它们似乎总是不合时宜。然而，在内心深处，我们似乎都想要它们。UNIX 的 <code>cp</code> 命令没有进度条，但它有一个 <code>-v</code> 选项用于显示详细信息，它回显了复制的每个文件名到终端。这是一个相当不错的技巧，但是当你复制一个大文件并且想要了解还有多少文件尚未传输时，它的作用就没那么大了。</p><p><code>pv</code> 命令可以在复制期间提供进度条，但它并不常用。另一方面，<code>rsync</code> 命令包含在几乎所有的 POSIX 系统的默认安装中，并且它被普遍认为是远程和本地复制文件的最智能方法之一。</p><p>更好的是，它有一个内置的进度条。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias cpv=&#39;rsync -ah --info=progress2&#39;</span></span></code></pre></div><p>像使用 <code>cp</code> 命令一样使用此别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cpv bigfile.flac /run/media/seth/audio/</span></span>
<span class="line"><span>          3.83M 6%  213.15MB/s    0:00:00 (xfr#4, to-chk=0/4)</span></span></code></pre></div><p>使用此命令的一个有趣的副作用是 <code>rsync</code> 无需 <code>-r</code> 标志就可以复制文件和目录，而 <code>cp</code> 则需要。</p><h3 id="避免意外删除" tabindex="-1">避免意外删除 <a class="header-anchor" href="#避免意外删除" aria-label="Permalink to “避免意外删除”">​</a></h3><p>你不应该使用 <code>rm</code> 命令。<code>rm</code> 手册甚至这样说：</p><blockquote><p><strong>警告：</strong>如果使用 <code>rm</code> 删除文件，通常可以恢复该文件的内容。如果你想要更加确保内容真正无法恢复，请考虑使用 <code>shred</code>。</p></blockquote><p>如果要删除文件，则应将文件移动到“废纸篓”，就像使用桌面时一样。</p>`,71)),n("p",null,[s[19]||(s[19]=a("POSIX 使这很简单，因为垃圾桶是文件系统中可访问的一个实际位置。该位置可能会发生变化，具体取决于你的平台：在 ",-1)),i(e,{href:"https://www.freedesktop.org/wiki/"},{default:p(()=>[...s[18]||(s[18]=[a("FreeDesktop",-1)])]),_:1}),s[20]||(s[20]=a(" 上，“垃圾桶”位于 ",-1)),s[21]||(s[21]=n("code",null,"~/.local/share/Trash",-1)),s[22]||(s[22]=a("，而在 MacOS 上则是 ",-1)),s[23]||(s[23]=n("code",null,"~/.Trash",-1)),s[24]||(s[24]=a("，但无论如何，它只是一个目录，你可以将文件藏在那个看不见的地方，直到你准备永久删除它们为止。",-1))]),s[49]||(s[49]=l(`<p>这个简单的别名提供了一种从终端将文件扔进垃圾桶的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias tcn=&#39;mv --force -t ~/.local/share/Trash &#39;</span></span></code></pre></div><p>该别名使用一个鲜为人知的 <code>mv</code> 标志（<code>-t</code>），使你能够提供作为最终移动目标的参数，而忽略了首先列出要移动的文件的通常要求。现在，你可以使用新命令将文件和文件夹移动到系统垃圾桶：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>foo  bar</span></span>
<span class="line"><span>$ tcn foo</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>bar</span></span></code></pre></div><p>现在文件已“消失”，只有在你一头冷汗的时候才意识到你还需要它。此时，你可以从系统垃圾桶中抢救该文件；这肯定可以给 Bash 和 <code>mv</code> 开发人员提供一些帮助。</p>`,5)),n("p",null,[s[26]||(s[26]=n("strong",null,"注意：",-1)),s[27]||(s[27]=a("如果你需要一个具有更好的 FreeDesktop 兼容性的更强大的垃圾桶命令，请参阅 ",-1)),i(e,{href:"https://gitlab.com/trashy/trashy"},{default:p(()=>[...s[25]||(s[25]=[a("Trashy",-1)])]),_:1}),s[28]||(s[28]=a("。",-1))]),s[50]||(s[50]=l(`<h3 id="简化-git-工作流" tabindex="-1">简化 Git 工作流 <a class="header-anchor" href="#简化-git-工作流" aria-label="Permalink to “简化 Git 工作流”">​</a></h3><p>每个人都有自己独特的工作流程，但无论如何，通常都会有重复的任务。如果你经常使用 Git，那么你可能会发现自己经常重复的一些操作序列。也许你会发现自己回到主分支并整天一遍又一遍地拉取最新的变化，或者你可能发现自己创建了标签然后将它们推到远端，抑或可能完全是其它的什么东西。</p><p>无论让你厌倦一遍遍输入的 Git 魔咒是什么，你都可以通过 Bash 别名减轻一些痛苦。很大程度上，由于它能够将参数传递给钩子，Git 拥有着丰富的内省命令，可以让你不必在 Bash 中执行那些丑陋冗长的命令。</p><p>例如，虽然你可能很难在 Bash 中找到项目的顶级目录（就 Bash 而言，它是一个完全随意的名称，因为计算机的绝对顶级是根目录），但 Git 可以通过简单的查询找到项目的顶级目录。如果你研究过 Git 钩子，你会发现自己能够找到 Bash 一无所知的各种信息，而你可以利用 Bash 别名来利用这些信息。</p><p>这是一个来查找 Git 项目的顶级目录的别名，无论你当前在哪个项目中工作，都可以将目录改变为顶级目录，切换到主分支，并执行 Git 拉取：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias startgit=&#39;cd \`git rev-parse --show-toplevel\` &amp;&amp; git checkout master &amp;&amp; git pull&#39;</span></span></code></pre></div><p>这种别名绝不是一个普遍有用的别名，但它演示了一个相对简单的别名如何能够消除大量繁琐的导航、命令和等待提示。</p><p>一个更简单，可能更通用的别名将使你返回到 Git 项目的顶级目录。这个别名非常有用，因为当你在一个项目上工作时，该项目或多或少会成为你的“临时家目录”。它应该像回家一样简单，就像回你真正的家一样，这里有一个别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias cg=&#39;cd \`git rev-parse --show-toplevel\`&#39;</span></span></code></pre></div><p>现在，命令 <code>cg</code> 将你带到 Git 项目的顶部，无论你下潜的目录结构有多深。</p><h3 id="切换目录并同时查看目录内容" tabindex="-1">切换目录并同时查看目录内容 <a class="header-anchor" href="#切换目录并同时查看目录内容" aria-label="Permalink to “切换目录并同时查看目录内容”">​</a></h3><p>（据称）曾经一位著名科学家提出过，我们可以通过收集极客输入 <code>cd</code> 后跟 <code>ls</code> 消耗的能量来解决地球上的许多能量问题。</p><p>这是一种常见的用法，因为通常当你更改目录时，你都会有查看周围的内容的冲动或需要。</p><p>但是在你的计算机的目录树中移动并不一定是一个走走停停的过程。</p><p>这是一个作弊，因为它根本不是别名，但它是探索 Bash 功能的一个很好的借口。虽然别名非常适合快速替换一个命令，但 Bash 也允许你在 <code>.bashrc</code> 文件中添加本地函数（或者你加载到 <code>.bashrc</code> 中的单独函数文件，就像你的别名文件一样）。</p><p>为了保持模块化，创建一个名为 <code>~/.bash_functions</code> 的新文件，然后让你的 <code>.bashrc</code> 加载它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -e $HOME/.bash_functions ]; then</span></span>
<span class="line"><span>    source $HOME/.bash_functions</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>在该函数文件中，添加这些代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function cl() {</span></span>
<span class="line"><span>    DIR=&quot;$*&quot;;</span></span>
<span class="line"><span>        # if no DIR given, go home</span></span>
<span class="line"><span>        if [ $# -lt 1 ]; then</span></span>
<span class="line"><span>                DIR=$HOME;</span></span>
<span class="line"><span>    fi;</span></span>
<span class="line"><span>    builtin cd &quot;\${DIR}&quot; &amp;amp;&amp;amp; \\</span></span>
<span class="line"><span>    # use your preferred ls command</span></span>
<span class="line"><span>        ls -F --color=auto</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>将函数加载到 Bash 会话中，然后尝试：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bash_functions</span></span>
<span class="line"><span>$ cl Documents</span></span>
<span class="line"><span>foo bar baz</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/seth/Documents</span></span>
<span class="line"><span>$ cl ..</span></span>
<span class="line"><span>Desktop  Documents  Downloads</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/seth</span></span></code></pre></div><p>函数比别名更灵活，但有了这种灵活性，你就有责任确保代码有意义并达到你的期望。别名是简单的，所以要保持简单而有用。要正式修改 Bash 的行为，请使用保存到 <code>PATH</code> 环境变量中某个位置的函数或自定义的 shell 脚本。</p><p>附注，有一些巧妙的奇技淫巧来实现 <code>cd</code> 和 <code>ls</code> 序列作为别名，所以如果你足够耐心，那么即使是一个简单的别名也永无止限。</p><h3 id="开始别名化和函数化吧" tabindex="-1">开始别名化和函数化吧 <a class="header-anchor" href="#开始别名化和函数化吧" aria-label="Permalink to “开始别名化和函数化吧”">​</a></h3><p>可以定制你的环境使得 Linux 变得如此有趣，提高效率使得 Linux 可以改变生活。开始使用简单的别名，进而使用函数，并在评论中发布你必须拥有的别名！</p><hr>`,26)),n("p",null,[s[30]||(s[30]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/19/7/bash-aliases"},{default:p(()=>[...s[29]||(s[29]=[a("https://opensource.com/article/19/7/bash-aliases",-1)])]),_:1})]),n("p",null,[s[35]||(s[35]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[31]||(s[31]=[a("Seth Kenlon",-1)])]),_:1}),s[36]||(s[36]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[32]||(s[32]=[a("lujun9972",-1)])]),_:1}),s[37]||(s[37]=a(" 译者：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[33]||(s[33]=[a("wxy",-1)])]),_:1}),s[38]||(s[38]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[34]||(s[34]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[41]||(s[41]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[39]||(s[39]=[a("LCTT",-1)])]),_:1}),s[42]||(s[42]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[40]||(s[40]=[a("Linux中国",-1)])]),_:1}),s[43]||(s[43]=a(" 荣誉推出",-1))])])}const C=t(r,[["render",c]]);export{v as __pageData,C as default};
